package glitch

import data.glitch_lib

suspicious_keywords := {"TODO", "HACK", "FIXME", "BUG", "INSECURE"}

security_sensitive_attributes := {"permission", "access", "secret", "exposure", "role", "policy", "admin", "encryption", "network", "firewall"}

has_suspicious_keyword(comment) {
    some kw in suspicious_keywords
    contains(comment.content, kw)
}

has_security_sensitive_attribute(atomic_unit) {
    attrs := glitch_lib.all_attributes(atomic_unit)
    attr := attrs[_]
    some sensitive_attr in security_sensitive_attributes
    contains(attr.name, sensitive_attr)
}

within_proximity(comment, atomic_unit) {
    atomic_unit.info.line >= comment.info.line
    atomic_unit.info.line <= comment.info.line + 5
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    comment := parent.comments[_]
    has_suspicious_keyword(comment)

    nearby_resources := {atomic_unit | atomic_unit := glitch_lib.all_atomic_units(parent)[_]; within_proximity(comment, atomic_unit); has_security_sensitive_attribute(atomic_unit)}
    count(nearby_resources) > 0

    result := {
        "type": "sec_susp_comm",
        "element": comment,
        "path": parent.path,
        "description": "Suspicious keyword in comment near security-sensitive resource. This may indicate a temporary or insecure fix that could introduce vulnerabilities. (CWE-710)"
    }
}

